def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data")
    if not isinstance(data, list) or len(data) == 0:
        raise Blocked("no community available")
    return statusCode == 200 and responseBody.get("code") == 0 and all(isinstance(item, dict) and item.get("id") and item.get("name") for item in data) and bool(responseBody.get("requestId"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data") or {}
    return statusCode == 200 and responseBody.get("code") == 0 and bool(data.get("user", {}).get("id")) and bool(data.get("accessToken")) and bool(data.get("refreshToken")) and bool(responseBody.get("requestId"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    message = responseBody.get("message")
    return statusCode == 400 and responseBody.get("code") == 40001 and isinstance(message, str) and "Exception" not in message and "SQL" not in message and bool(responseBody.get("requestId"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    return statusCode == 200 and responseBody.get("code") == 0 and responseBody.get("data") == {} and bool(responseBody.get("requestId"))
